import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useEffect, useState } from "react";
import "./Profile.css"; // custom CSS

export default function Profile() {
  const [profile, setProfile] = useState({
    fullName: "",
    email: "",
    phone: "",
    role: "Software Engineer",
    bio: ""
  });

  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token");
      if (!token) return;

      try {
        const response = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (response.ok) {
          const data = await response.json();
          setProfile({
            fullName: `${data.first_name || ""} ${data.last_name || ""}`,
            email: data.email || "",
            phone: data.profile?.phone || "",
            bio: data.profile?.bio || "",
            role: "Software Engineer"
          });
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchProfile();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem("token");
    if (!token) return;

    const [first_name, ...rest] = profile.fullName.split(" ");
    const last_name = rest.join(" ");

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/users/me/`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          first_name,
          last_name,
          email: profile.email,
          profile: {
            phone: profile.phone,
            bio: profile.bio
          }
        })
      });

      if (response.ok) {
        setMessage("✅ Profile updated successfully!");
      } else {
        setMessage("❌ Failed to update profile");
      }
    } catch (err) {
      console.error(err);
      setMessage("⚠️ Network error. Try again later.");
    }
  };

  if (loading) return <p>Loading profile...</p>;

  return (
    <div className="profile-wrapper">
      {/* Left Side - Profile Form */}
      <div className="profile-content">
        <h1 className="profile-title">My Profile</h1>
        <p className="profile-subtitle">Manage your personal information</p>

        <form onSubmit={handleSubmit} className="profile-form">
          <div className="form-group">
            <label>Full Name</label>
            <input
              type="text"
              className="form-control-modern"
              name="fullName"
              value={profile.fullName}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Email Address</label>
            <input
              type="email"
              className="form-control-modern"
              name="email"
              value={profile.email}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Phone Number</label>
            <input
              type="tel"
              className="form-control-modern"
              name="phone"
              value={profile.phone}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label>Role</label>
            <input
              type="text"
              className="form-control-modern"
              value={profile.role}
              readOnly
            />
          </div>

          <div className="form-group">
            <label>Bio</label>
            <textarea
              className="form-control-modern"
              name="bio"
              rows="3"
              value={profile.bio}
              onChange={handleChange}
            ></textarea>
          </div>

          <button type="submit" className="btn-save">Save Changes</button>
          {message && <p className="message">{message}</p>}
        </form>
      </div>

      {/* Right Side - Illustration */}
      <div className="profile-illustration">
        <img
          src="https://cdn.dribbble.com/users/25514/screenshots/16524445/media/8a5d89c2e4c2dcdcf2b9f1c617a19e1a.png"
          alt="Profile Illustration"
        />
      </div>
    </div>
  );
}
